% op_gaussianPeak.m
% Jamie Near, McGill University 2014.
% 
% USAGE:
% out=op_gaussianPeak(n,sw,Bo,centerFreq,lw,ppm0,amp);
% 
% DESCRIPTION:
% Generate a noiseless spectrum containing a single gaussian peak with
% desired parameters (frequency, amplitude, linewidth, etc.).
% 
% INPUTS:
% n             = Number of points in spectrum.
% sw            = spectral width of spectrum (Hz).
% Bo            = Magnetic field strength (Tesla).
% centerFreq    = center frequency of the spectrum (ppm).
% lw            = Linewidth of gaussian peak (Hz).
% ppm0          = Frequency of gaussian peak (ppm).
% amp           = Amplitude of gaussian peak.  
%
% OUTPUTS:
% out    = Gaussian lineshape peak in FID-A structure format 


function out=op_gaussianPeak(n,sw,Bo,centerFreq,lw,ppm0,amp);

dt=1/sw;
df=sw/n;
decay=1/(lw*pi);
f0=(-centerFreq+ppm0)*(Bo*42.577)* 2 * pi;

t=[0:dt:(n-1)*dt];
f=[(-sw/2+(df/2)):df:(sw/2-(df/2))];

ppm=f/(Bo*42.577);
ppm=ppm+4.68;
ppm=ppm-(4.68-centerFreq);

fids=amp * exp(-(t.^2)/(2*(decay^2))) .* exp(-1j*f0*t);
fids=fids';

specs=fftshift(fft(fids,[],1),1);

out.t=t;
out.fids=fids;
out.ppm=ppm;
out.specs=specs;

%FILLING IN DATA STRUCTURE

out.sz=size(out.fids);
out.spectralwidth=sw;
out.dwelltime=dt;
out.txfrq=Bo*42.577;
out.centerFreq=centerFreq;
out.date=date;
out.dims.t=1;
out.dims.averages=0;
out.dims.subSpecs=0;
out.dims.coils=0;
out.Bo=Bo;
out.averages=1;
out.rawAverages=1;
out.subspecs=1;
out.rawSubspecs=1;

%FILLING IN THE FLAGS
out.flags.writtentostruct=1;
out.flags.gotparams=1;
out.flags.leftshifted=0;
out.flags.filtered=0;
out.flags.zeropadded=0;
out.flags.freqcorrected=0;
out.flags.phasecorrected=0;
out.flags.averaged=0;
out.flags.addedrcvrs=0;
out.flags.subtracted=0;
out.flags.writtentotext=0;
out.flags.downsampled=0;
if out.dims.subSpecs==0
    out.flags.isFourSteps=0;
else
    out.flags.isFourSteps=(out.sz(out.dims.subSpecs)==4);
end

% op_lorentz.m
% Jamie Near, McGill University 2014.
% 
% USAGE:
% y=op_lorentz(pars,ppm);
% 
% DESCRIPTION:  
% Generate a parametrized lorentzian peak.
% This function is fed into fitting tools to enable fitting of peaks using
% lorentzian lineshapes.
% 
% INPUTS:
% pars       = The parameters of the Lorentizan function.  This is a five 
%             element vector consisting of the following fields:
%             [ Amplitude, 
%               FWHM, (In Hz) 
%               Centre Freq,  (In ppm)
%               baseline offset, (in Amplitude units)
%               Phase shift];  (in degrees)
% ppm        = frequency axis vector (in ppm);
%
% OUTPUTS:
% y          = Output vector specifying a lorentzian lineshape.  



function [y]=op_lorentz(pars,ppm)

A=pars(:,1);     %Amplitude  (Use only positive Numbers)
w=pars(:,2);     %full width at half max
ppm0=pars(:,3);  %centre frequency of peak

if size(pars,2)==5
    y0=pars(:,4);    %baseline offset
    theta=pars(:,5); %Phase shift of peak
    gam=w/2;      %gamma parameter
    %Define a complex lorentzian for each set of
    y=zeros(length(A),length(ppm));
    for n=1:length(A)
        y(n,:) = sqrt(2/pi) *(gam(n)-i*(ppm-ppm0(n))) ./ (gam(n)^2 + (ppm-ppm0(n)).^2);
        %now scale it, add baseline, phase it by theta, and take the real part
        y(n,:)=real(addphase(y(n,:)/max(abs(y(n,:)))*A(n)+y0(n),theta(n)));
    end
    y=sum(y,1);
elseif size(pars,2)==4
    y0=pars(:,4);    %baseline offset
    gam=w/2;      %gamma parameter
    %assume zero phase:
    theta=zeros(size(pars,1),1);
    %Define a complex lorentzian for each set of
    y=zeros(length(A),length(ppm));
    for n=1:length(A)
        y(n,:) = sqrt(2/pi) *(gam(n)-i*(ppm-ppm0(n))) ./ (gam(n)^2 + (ppm-ppm0(n)).^2);
        %now scale it, add baseline, phase it by theta, and take the real part
        y(n,:)=real(addphase(y(n,:)/max(abs(y(n,:)))*A(n)+y0(n),theta(n)));
    end
    y=sum(y,1);
elseif size(pars,2)==3
    gam=w/2;      %gamma parameter
    %assume zero phase:
    theta=zeros(size(pars,1),1);
    %assume zero baseline offset:
    y0=zeros(size(pars,1),1);
    %Define a complex lorentzian for each set of
    y=zeros(length(A),length(ppm));
    for n=1:length(A)
        y(n,:) = sqrt(2/pi) *(gam(n)-i*(ppm-ppm0(n))) ./ (gam(n)^2 + (ppm-ppm0(n)).^2);
        %now scale it, add baseline, phase it by theta, and take the real part
        y(n,:)=real(addphase(y(n,:)/max(abs(y(n,:)))*A(n)+y0(n),theta(n)));
    end
    y=sum(y,1);
end






% op_dccorr.m
% Jamie Near, McGill University 2014.
% 
% USAGE:
% [out,dcOffset]=op_dccorr(in,mode,var1);
% 
% DESCRIPTION:
% Do a DC Correction on the data.  This method is a frequency domain
% operation.
% 
% INPUTS:
% in	= input data in matlab structure format.  
% mode	= ppmrange('p') or Value('v').  In ppmrange mode, the DC offset is
%           calculated automatically over a defined ppm range in the 
%           spectrum.  In value mode, the user has to provide the value of 
%           the desired DC offset.
% var1	= If mode is 'p', then 'var1' is the range of ppm values 
%           [minppm maxppm] over which to calculate the DC offset.  In 
%           ppmrange mode, the 'var1' is optional, and takes a default 
%           value of [max(in.ppm)-0.5 max(in.ppm] AND 
%           [min(in.ppm) min(in.ppm)+0.5].  If mode is 'v', then 'var1' is 
%           the value of the dc offset correction that you wish to employ.
%
% OUTPUTS:
% out   = Output following DC correction.  

function [out,dcOffset]=op_dccorr(in,mode,var1);

if mode=='p'
    if nargin<3
        var1a=[max(in.ppm)-0.5 max(in.ppm)];
        var1b=[min(in.ppm) min(in.ppm)+0.5];
        dcOffset1=mean(in.specs(in.ppm<var1a(2) & in.ppm>var1a(1)));
        dcOffset2=mean(in.specs(in.ppm<var1b(2) & in.ppm>var1b(1)));
        dcOffset=mean([dcOffset1 dcOffset2]);
    else
        dcOffset=mean(in.specs(in.ppm<var1(2) & in.ppm>var1(1)));
    end
elseif mode=='v'
    dcOffset=var1;
end

specs=in.specs-dcOffset;

%convert back to time domain
%if the length of Fids is odd, then you have to do a circshift of one to
%make sure that you don't introduce a small frequency shift into the fids
%vector.
if mod(size(specs,in.dims.t),2)==0
    %disp('Length of vector is even.  Doing normal conversion');
    fids=ifft(fftshift(specs,in.dims.t),[],in.dims.t);
else
    %disp('Length of vector is odd.  Doing circshift by 1');
    fids=ifft(circshift(fftshift(specs,in.dims.t),1),[],in.dims.t);
end

%FILLING IN DATA STRUCTURE
out=in;
out.fids=fids;
out.specs=specs;

%FILLING IN THE FLAGS
out.flags=in.flags;
out.flags.writtentostruct=1;
out.flags.freqranged=1;

function [MRSCont] = osp_fitHERCULES(MRSCont)
%% [MRSCont] = osp_fitHERCULES(MRSCont)
%   This function performs spectral fitting of HERMES MRS data.
%
%   USAGE:
%       [MRSCont] = osp_fitHERCULES(MRSCont);
%
%   INPUTS:
%       MRSCont     = Osprey MRS data container.
%
%   OUTPUTS:
%       MRSCont     = Osprey MRS data container.
%
%   AUTHOR:
%       Dr. Georg Oeltzschner (Johns Hopkins University, 2019-04-12)
%       goeltzs1@jhmi.edu
%
%   CREDITS:
%       This code is based on numerous functions from the FID-A toolbox by
%       Dr. Jamie Near (McGill University)
%       https://github.com/CIC-methods/FID-A
%       Simpson et al., Magn Reson Med 77:23-33 (2017)
%
%   HISTORY:
%       2019-04-12: First version of the code.


% Loop over all the datasets here
metFitTime = tic;
if MRSCont.flags.isGUI
    progressText = MRSCont.flags.inProgress;
else
    progressText = '';
end
for kk = 1:MRSCont.nDatasets
    [~] = printLog('OspreyFit',kk,1,MRSCont.nDatasets,progressText,MRSCont.flags.isGUI ,MRSCont.flags.isMRSI); 
    %%% 1. DETERMINE THE FITTING STYLE %%%
    % Extract fit options
    fitOpts     = MRSCont.opts.fit;
    fitModel    = fitOpts.method;
    fitStyle    = fitOpts.style;


    %%% 2. SEPARATE FIT %%%
    % For the separate (classic) HERMES fit, model the two DIFF
    % spectra and the SUM spectrum separately.
    if strcmp(fitStyle, 'Separate')
        if ~(MRSCont.flags.didFit == 1 && MRSCont.flags.speedUp && isfield(MRSCont, 'fit') && (kk > size(MRSCont.fit.results.metab.fitParams,2))) || ~strcmp(MRSCont.ver.Osp,MRSCont.ver.CheckOsp)  

            %%% 2a. FIT SUM-SPECTRUM
            % Apply scaling factor to the data
            dataToFit   = op_takesubspec(MRSCont.processed.metab{kk},'sum');
            basisSetSum = MRSCont.fit.basisSet;
            basisSetSum.fids = basisSetSum.fids(:,:,7);
            basisSetSum.specs = basisSetSum.specs(:,:,7);
            dataToFit   = op_ampScale(dataToFit, 1/MRSCont.fit.scale{kk});

            fitOpts.GAP = MRSCont.opts.fit.GAP.sum;
            % Call the fit function
            [fitParamsSum, resBasisSetSum] = fit_runFit(dataToFit, basisSetSum, fitModel, fitOpts);

            % Save back the basis set and fit parameters to MRSCont
            MRSCont.fit.resBasisSet.metab{1,kk,1}             = resBasisSetSum;
            MRSCont.fit.results.metab.fitParams{1,kk,1}   = fitParamsSum;


            %%% 2b. FIT DIFF1-SPECTRUM
            % Apply scaling factor to the data
            dataToFit   = op_takesubspec(MRSCont.processed.metab{kk},'diff1');
            basisSetDiff1 = MRSCont.fit.basisSet;
            basisSetDiff1.fids = basisSetDiff1.fids(:,:,5);
            basisSetDiff1.specs = basisSetDiff1.specs(:,:,5);
            dataToFit   = op_ampScale(dataToFit, 1/MRSCont.fit.scale{kk});
            dataToFit.refShift   = fitParamsSum.refShift;
            dataToFit.refFWHM   = fitParamsSum.refFWHM;

            if isfield(fitOpts, 'coMM3') && ~strcmp(fitOpts.coMM3, 'none')
                [basisSetDiff1] = osp_addDiffMMPeaks(basisSetDiff1,basisSetSum,fitOpts);
            end

            fitOpts.GAP = MRSCont.opts.fit.GAP.diff1;
            % Call the fit function
            [fitParamsDiff1, resBasisSetDiff1]  = fit_runFit(dataToFit, basisSetDiff1, fitModel, fitOpts);

            % Save back the basis set and fit parameters to MRSCont
            MRSCont.fit.resBasisSet.metab{1,kk,2}           = resBasisSetDiff1;
            MRSCont.fit.results.metab.fitParams{1,kk,2} = fitParamsDiff1;


            %%% 2c. FIT DIFF2-SPECTRUM
            % Apply scaling factor to the data
            dataToFit   = op_takesubspec(MRSCont.processed.metab{kk},'diff2');
            basisSetDiff2 = MRSCont.fit.basisSet;
            basisSetDiff2.fids = basisSetDiff2.fids(:,:,6);
            basisSetDiff2.specs = basisSetDiff2.specs(:,:,6);
            dataToFit   = op_ampScale(dataToFit, 1/MRSCont.fit.scale{kk});
            dataToFit.refShift   = fitParamsSum.refShift;
            dataToFit.refFWHM   = fitParamsSum.refFWHM;
            fitOpts.Diff2 = 1;

            fitOpts.GAP = MRSCont.opts.fit.GAP.diff2;
            % Call the fit function
            [fitParamsDiff2, resBasisSetDiff2]  = fit_runFit(dataToFit, basisSetDiff2, fitModel, fitOpts);

            % Save back the basis set and fit parameters to MRSCont
            MRSCont.fit.resBasisSet.metab{1,kk,3}           = resBasisSetDiff2;
            MRSCont.fit.results.metab.fitParams{1,kk,3} = fitParamsDiff2;
        end
    end


    %%% 3. CONCATENATED FIT %%%
    % For the concatenated MEGA fit, model the DIFF1 and SUM spectra
    % together.
    if strcmp(fitStyle, 'Concatenated')
        if ~(MRSCont.flags.didFit == 1 && MRSCont.flags.speedUp && isfield(MRSCont, 'fit') && (kk > length(MRSCont.fit.results.conc.fitParams))) || ~strcmp(MRSCont.ver.Osp,MRSCont.ver.CheckOsp)   

            %%% 3a. FIT CONCATENATED SPECTRUM
            % Apply scaling factor to the data
            dataToFit   = {op_takesubspec(MRSCont.processed.metab{kk},7), op_takesubspec(MRSCont.processed.metab{kk},5), op_takesubspec(MRSCont.processed.metab{kk},6)};
            basisSetConc = MRSCont.fit.basisSet;
            basisSetConc.fids = basisSetConc.fids(:,:,5:7);
            basisSetConc.specs = basisSetConc.specs(:,:,5:7);
            for rr = 1:length(dataToFit)
                dataToFit{rr}   = op_ampScale(dataToFit{rr}, 1/MRSCont.fit.scale{kk});
            end

            % Call the fit function
            [fitParamsConc, resBasisSetConc] = fit_runFitMultiplex(dataToFit, basisSetConc, fitModel, fitOpts);

            % Save back the basis set and fit parameters to MRSCont
            MRSCont.fit.resBasisSet.conc{kk}           = resBasisSetConc;
            MRSCont.fit.results.conc.fitParams{kk} = fitParamsConc;
        end
    end
end
time = toc(metFitTime);
[~] = printLog('done',time,1,MRSCont.nDatasets,progressText,MRSCont.flags.isGUI ,MRSCont.flags.isMRSI);
MRSCont.runtime.FitMet = time;

end

function [MRSCont] = OspreyQuantify(MRSCont)
%% [MRSCont] = OspreyQuantify(MRSCont)
%   This function transforms the raw amplitude parameters determined during
%   OspreyFit into quantitative estimates of metabolite levels.
%
%   By default, OspreyQuantify will report tCr ratios for all metabolites.
%   These values will not undergo any further correction for tissue
%   content, or relaxation.
%
%   If some sort of unsuppressed data has been provided, OspreyQuantify will
%   calculate concentration estimates in institutional units. These values
%   will have varying degrees of corrections and assumptions.
%
%   USAGE:
%       MRSCont = OspreyQuantify(MRSCont);
%
%   INPUTS:
%       MRSCont     = Osprey MRS data container.
%
%   OUTPUTS:
%       MRSCont     = Osprey MRS data container.
%
%   AUTHOR:
%       Dr. Georg Oeltzschner (Johns Hopkins University, 2019-10-09)
%       goeltzs1@jhmi.edu
%
%   CREDITS:
%       This code is based on numerous functions from the FID-A toolbox by
%       Dr. Jamie Near (McGill University)
%       https://github.com/CIC-methods/FID-A
%       Simpson et al., Magn Reson Med 77:23-33 (2017)
%
%   HISTORY:
%       2019-10-09: First version of the code.
%       2019-10-22: HZ added tables.

outputFolder = MRSCont.outputFolder;
diary(fullfile(outputFolder, 'LogFile.txt'));

% Checking for version, toolbox, and previously run modules
[~,MRSCont.ver.CheckOsp ] = osp_CheckRunPreviousModule(MRSCont, 'OspreyQuantify');


%%% 0. CHECK WHICH QUANTIFICATIONS CAN BE DONE %%%
% tCr ratios can always be calculated (unless the unlikely case that Cr is
% not in the basis set, a case we'll omit for now).
qtfyCr = 1;

% Check which types of metabolite data are available
SubSpectraFitted =size(MRSCont.fit.results.metab.fitParams,3);
BasisSetsFitted =size(MRSCont.fit.results.metab.fitParams,1);


% Check which types of water data are available
if [MRSCont.flags.hasRef MRSCont.flags.hasWater] == [1 1]
        % If both water reference and short-TE water data have been
        % provided, use the one with shorter echo time.
        qtfyH2O     = 1;
        waterType   = 'w';
elseif [MRSCont.flags.hasRef MRSCont.flags.hasWater] == [1 0]
        % If only one type of water data has been provided, use it.
        qtfyH2O     = 1;
        waterType   = 'ref';
elseif [MRSCont.flags.hasRef MRSCont.flags.hasWater] == [0 1]
        % If only one type of water data has been provided, use it.
        qtfyH2O     = 1;
        waterType   = 'w';
elseif [MRSCont.flags.hasRef MRSCont.flags.hasWater] == [0 0]
        % If no water ref has been provided, only tCr ratios can be
        % provided.
        qtfyH2O     = 0;
end

% Get the fieldstrength for proper relaxation correction
if qtfyH2O
    Bo = MRSCont.raw{1}.Bo;
    if (Bo >= 2.8 && Bo < 3.1)
            Bo = '3T';
    else
            Bo = '7T';
    end
end
% Check whether segmentation has been run, and whether tissue parameters
% exist. In that case, we can do CSF correction, and full tissue
% correction.
if qtfyH2O == 1 && MRSCont.flags.didSeg && isfield(MRSCont.seg, 'tissue')
    qtfyCSF     = 1;
    qtfyTiss    = 1;
else
    qtfyCSF     = 0;
    qtfyTiss    = 0;
end

% Check whether tissue correction is available and whether GABA-edited
% MEGA-PRESS has been run. In this case, we can apply the alpha correction
% (Harris et al, J Magn Reson Imaging 42:1431-40 (2015)).
if qtfyTiss == 1 && MRSCont.flags.isMEGA && (strcmp(MRSCont.opts.editTarget{1},'GABA'))
    qtfyAlpha   = 1;
else if qtfyTiss == 1 && (MRSCont.flags.isHERMES || MRSCont.flags.isHERCULES) && (strcmp(MRSCont.opts.editTarget{1},'GABA') || strcmp(MRSCont.opts.editTarget{2},'GABA'))
    qtfyAlpha   = 1;
     else
        qtfyAlpha   = 0;
    end
end

warning('off','all');

% Set up saving location
saveDestination = fullfile(MRSCont.outputFolder, 'QuantifyResults');
if ~exist(saveDestination,'dir')
    mkdir(saveDestination);
end


% Add combinations of metabolites to the basisset
for ss = 1 : SubSpectraFitted
    if ~strcmp(MRSCont.opts.fit.method, 'LCModel')
        for mm = 1 : BasisSetsFitted
            if ~isempty(MRSCont.fit.resBasisSet.metab.(MRSCont.info.metab.unique_ndatapoint_spectralwidth{1}){mm,1,ss})
                if ~iscell(MRSCont.fit.results) %Is SVS
                    MRSCont.quantify.names.metab{mm,ss} = MRSCont.fit.resBasisSet.metab.(MRSCont.info.metab.unique_ndatapoint_spectralwidth{1}){mm,1,ss}.name;
                    MRSCont.quantify.names.SubSpectra{mm,ss} = MRSCont.fit.resBasisSet.metab.(MRSCont.info.metab.unique_ndatapoint_spectralwidth{1}){mm,1,ss}.names{1};
                else %Is DualVoxel
                   MRSCont.quantify.names.metab{mm,ss} = MRSCont.fit.resBasisSet{1,1}.metab.(MRSCont.info.metab.unique_ndatapoint_spectralwidth{1}){mm,1,ss}.name;
                   MRSCont.quantify.names.SubSpectra{mm,ss} = MRSCont.fit.resBasisSet{1,1}.metab.(MRSCont.info.metab.unique_ndatapoint_spectralwidth{1}){mm,1,ss}.names{1};
                end
            end
        end
    else
        MRSCont.quantify.names.metab{1,1} = MRSCont.fit.results.metab.fitParams{1, 1}.name;
        MRSCont.quantify.names.SubSpectra{1,1} = MRSCont.processed.metab{1, 1}.names{1};
    end
end

for ss = 1 : SubSpectraFitted
    for kk = 1:MRSCont.nDatasets(1)
        for mm = 1 : BasisSetsFitted
            if ~isempty(MRSCont.quantify.names.metab{mm,ss})
                if  ~iscell(MRSCont.fit.results) %Is SVS %Is SVS
                    MRSCont.quantify.amplMets{mm,kk,ss}.metab = MRSCont.fit.results.metab.fitParams{mm,kk,ss}.ampl;
                else %Is DualVoxel
                   MRSCont.quantify.amplMets{mm,kk,ss}.metab(:,1) = MRSCont.fit.results{1}.metab.fitParams{mm,kk,ss}.ampl;
                   MRSCont.quantify.amplMets{mm,kk,ss}.metab(:,2) = MRSCont.fit.results{2}.metab.fitParams{mm,kk,ss}.ampl;
                end
            end
        end
    end
end

if strcmp(MRSCont.opts.fit.method, 'LCModel')
    for kk = 1:MRSCont.nDatasets(1)
        if  ~iscell(MRSCont.fit.results) %Is SVS %Is SVS
            MRSCont.quantify.CRLB{kk}.metab = MRSCont.fit.results.metab.fitParams{kk}.CRLB';
            MRSCont.quantify.h2oarea{kk}.metab = MRSCont.fit.results.metab.fitParams{kk}.h2oarea;
        else %Is DualVoxel
            MRSCont.quantify.CRLB{kk}.metab(:,1) = MRSCont.fit.results{1}.metab.fitParams{kk}.CRLB';
           MRSCont.quantify.CRLB{kk}.metab(:,2) = MRSCont.fit.results{2}.metab.fitParams{kk}.CRLB';
           MRSCont.quantify.h2oarea{kk}.metab(:,1) = MRSCont.fit.results{1}.metab.fitParams{kk}.h2oarea;
           MRSCont.quantify.h2oarea{kk}.metab(:,2) = MRSCont.fit.results{2}.metab.fitParams{kk}.h2oarea;
        end
    end
end

MRSCont = addMetabComb(MRSCont);


%% Loop over all datasets
QuantifyTime = tic;
if MRSCont.flags.isGUI && isfield(MRSCont.flags,'inProgress')
    progressText = MRSCont.flags.inProgress;
else
    progressText = '';
end
fprintf('\n');
if MRSCont.flags.isGUI && isfield(MRSCont.flags,'inProgress')
    progressText = MRSCont.flags.inProgress;
end
for kk = 1:MRSCont.nDatasets(1)
    [~] = printLog('OspreyQuant',kk,1,MRSCont.nDatasets,progressText,MRSCont.flags.isGUI ,MRSCont.flags.isMRSI);

    %%% 1. GET BASIS SET AND FIT AMPLITUDES %%%
    metsName = MRSCont.quantify.names; % just for the names
    amplMets = MRSCont.quantify.amplMets(:,kk,:);


    %%% 2. GET CREATINE RATIOS %%%
    % We can always do this, but let's use the flag just to be safe:
    if qtfyCr

        % Extract metabolite amplitudes from fit
        tCrRatios = quantCr(metsName, amplMets);

        % Save back to Osprey data container
        for ss = 1 :SubSpectraFitted
            for mm = 1 :BasisSetsFitted
                if ~isempty( tCrRatios{mm,ss})
                    MRSCont.quantify.metab.tCr{mm,kk,ss}  = tCrRatios{mm,ss}.metab;
                end
            end
        end

    end


    %%% 3. GET WATER-SCALED, TISSUE-UNCORRECTED RATIOS %%%
    if qtfyH2O
        if ~strcmp(MRSCont.opts.fit.method, 'LCModel')
            if  ~iscell(MRSCont.fit.results) %Is SVS %Is SVS
                amplWater = MRSCont.fit.results.(waterType).fitParams{kk}.ampl;
            else %Is DualVoxel
               amplWater(:,1) = MRSCont.fit.results{1}.(waterType).fitParams{kk}.ampl;
               amplWater(:,2) = MRSCont.fit.results{2}.(waterType).fitParams{kk}.ampl;
            end
        else
            % Get WCONC, ATTMET, and ATTH2O from control file
            LCMparam = osp_readlcm_control(MRSCont.opts.fit.lcmodel.controlfileA{kk});
            if isfield(LCMparam, 'WCONC') % User-supplied WCONC
                amplWater = str2double(LCMparam.WCONC);
            else
                amplWater = 35880; %LCModel default WCONC assumes pure WM
            end

            if isfield(LCMparam, 'ATTMET') % User-supplied ATTMET
                amplWater = amplWater * str2double(LCMparam.ATTMET);
            else
                 %Do nothing as LCModel default ATTMET is 1
            end

            if isfield(LCMparam, 'ATTH2O') % User-supplied ATTH2O
                amplWater = amplWater / str2double(LCMparam.ATTH2O);
            else
                amplWater = amplWater / 0.7; %LCModel default ATTH2O is 0.7
            end
        end

        % Get repetition times
        metsTR  = MRSCont.processed.metab{kk}.tr * 1e-3;
        waterTR = MRSCont.processed.(waterType){kk}.tr * 1e-3;
        % Get echo times
        metsTE  = MRSCont.processed.metab{kk}.te * 1e-3;
        waterTE = MRSCont.processed.(waterType){kk}.te * 1e-3;
        % Calculate water-scaled, but not tissue-corrected metabolite levels
        rawWaterScaled = quantH2O(metsName, amplMets, amplWater, metsTR, waterTR, metsTE, waterTE,Bo);

        % Save back to Osprey data container
        for ss = 1 :SubSpectraFitted
            for mm = 1 :BasisSetsFitted
                if ~isempty( rawWaterScaled{mm,ss})
                    MRSCont.quantify.metab.rawWaterScaled{mm,kk,ss} = rawWaterScaled{mm,ss}.metab;
                end
            end
        end

    end


    %%% 4. GET CSF CORRECTION %%%
    if qtfyCSF

        % Apply CSF correction
        fCSF = MRSCont.seg.tissue.fCSF(kk,:);
        CSFWaterScaled = quantCSF(rawWaterScaled, fCSF,SubSpectraFitted);

        % Save back to Osprey data container
        for ss = 1 :SubSpectraFitted
            for mm = 1 :BasisSetsFitted
                if ~isempty( CSFWaterScaled{mm,ss})
                    MRSCont.quantify.metab.CSFWaterScaled{mm,kk,ss} = CSFWaterScaled{mm,ss}.metab;
                end
            end
        end
    end


    %%% 5. GET TISSUE CORRECTION %%%
    if qtfyTiss

        % Apply tissue correction
        fGM = MRSCont.seg.tissue.fGM(kk,:);
        fWM = MRSCont.seg.tissue.fWM(kk,:);
        TissCorrWaterScaled = quantTiss(metsName, amplMets, amplWater, metsTR, waterTR, metsTE, waterTE, fGM, fWM, fCSF,Bo);

        % Save back to Osprey data container
        for ss = 1 :SubSpectraFitted
            for mm = 1 :BasisSetsFitted
                if ~isempty( TissCorrWaterScaled{mm,ss})
                    MRSCont.quantify.metab.TissCorrWaterScaled{mm,kk,ss} = TissCorrWaterScaled{mm,ss}.metab;
                end
            end
        end
    end


    %%% 6. GET ALPHA CORRECTION (THIS IS FOR GABA ONLY AT THIS POINT) %%%
    if qtfyAlpha

        % For now, this is done for GABA only; however, the principle
        % could be extended to other metabolites, as long as we have some
        % form of prior knowledge about their concentrations in GM and WM.
        fGM = MRSCont.seg.tissue.fGM;
        fWM = MRSCont.seg.tissue.fWM;

        % We don't want to remove excluded subjects from the alpah
        % correction.
%         if isfield(MRSCont,'exclude')
%             fGM(MRSCont.exclude) = nan;
%             fWM(MRSCont.exclude) = nan;
%         end
        % Calculate mean WM/GM fractions
        meanfGM = mean(MRSCont.seg.tissue.fGM,1); % average GM fraction across datasets
        meanfWM = mean(MRSCont.seg.tissue.fWM,1); % average WM fraction across datasets
        [AlphaCorrWaterScaled, AlphaCorrWaterScaledGroupNormed] = quantAlpha(metsName,amplMets, amplWater, metsTR, waterTR, metsTE, waterTE, fGM, fWM, fCSF, meanfGM, meanfWM,MRSCont.opts.fit.coMM3,Bo);

        % Save back to Osprey data container
        for ss = 1 :SubSpectraFitted
            for mm = 1 :BasisSetsFitted
                MRSCont.quantify.metab.AlphaCorrWaterScaled{mm,kk,ss} = AlphaCorrWaterScaled{mm,ss};
                MRSCont.quantify.metab.AlphaCorrWaterScaledGroupNormed{mm,kk,ss} = AlphaCorrWaterScaledGroupNormed{mm,ss};
            end
        end
    end
end
time = toc(QuantifyTime);
[~] = printLog('done',time,1,MRSCont.nDatasets,progressText,MRSCont.flags.isGUI ,MRSCont.flags.isMRSI);
MRSCont.runtime.Quantify = time;
%% Create tables
% Set up readable tables for each quantification.
[MRSCont] = osp_createTable(MRSCont,'amplMets');
if qtfyCr
    [MRSCont] = osp_createTable(MRSCont,'tCr');
end
if qtfyH2O
    [MRSCont] = osp_createTable(MRSCont,'rawWaterScaled');
end
if qtfyCSF
    [MRSCont] = osp_createTable(MRSCont,'CSFWaterScaled');
end
if qtfyTiss
    [MRSCont] = osp_createTable(MRSCont,'TissCorrWaterScaled');
end
if qtfyAlpha
    [MRSCont] = osp_createTable(MRSCont,'AlphaCorrWaterScaled');
    [MRSCont] = osp_createTable(MRSCont,'AlphaCorrWaterScaledGroupNormed');
end
%Generate tables from LCModel specific outputs
if strcmp(MRSCont.opts.fit.method, 'LCModel')
    [MRSCont] = osp_createTable(MRSCont,'CRLB');
    if qtfyH2O
     [MRSCont] = osp_createTable(MRSCont,'h2oarea');
    end
end
%% Clean up and save
% Set exit flags
MRSCont.flags.didQuantify           = 1;
diary off
% Save the metabolite tables as TSV with JSON sidecars
exportQuant(MRSCont,saveDestination);
%   Remove amplitudes table
MRSCont.quantify.tables.metab = rmfield(MRSCont.quantify.tables.metab,{'amplMets'});
% Save the output structure to the output folder
% Determine output folder
outputFolder    = MRSCont.outputFolder;
outputFile      = MRSCont.outputFile;
if ~exist(outputFolder,'dir')
    mkdir(outputFolder);
end

if MRSCont.flags.isGUI
    MRSCont.flags.isGUI = 0;
    save(fullfile(outputFolder, outputFile), 'MRSCont','-v7.3');
    MRSCont.flags.isGUI = 1;
else
   save(fullfile(outputFolder, outputFile), 'MRSCont','-v7.3');
end

end

