        % CPMG for T2, IR for T1
        % T2GM = 99 +/ 7, lit: 71+/- 10 (27)
        % T1GM = 1820 +/- 114, lit 1470 +/- 50 (29)
        % T2WM = 69 +/-3 lit 56 +/- 4 (27)
        % T1WM = 1084 +/- 45 lit 1110 +/- 45 (29)
        T1w_WM    = 0.832;
        T2w_WM    = 0.0792;
        T1w_GM    = 1.331;
        T2w_GM    = 0.110;
        T1w_CSF   = 3.817;
        T2w_CSF   = 0.503;
    case '7T'
        % Water relaxation 7 T
         % T1 from Rooney et al. 2007 (MRM)
         % T2 from Bartha et al. 2002 (MRM)
        T1w_WM    = 1.220;
        T2w_WM    = 0.050;
        T1w_GM    = 2.130;
        T2w_GM    = 0.055;
        T1w_CSF   = 4.425;
        T2w_CSF   = 0.141;
end

