        if ~isempty(find(strcmp(metsName.metab{mm,ss},'GABAplus')))
            % GABA (Harris et al, J Magn Reson Imaging 42:1431-1440 (2015))
            idx_GABAp  = find(strcmp(metsName.metab{mm,ss},'GABAplus'));
