  s = load(['fixtures/study_record_' rec{1} '.mat']);
  metsTR = s.metabolite_tr_ms * 1e-3;  % calling code: ms -> s
  waterTR = s.reference_tr_ms * 1e-3;
  metsTE = s.metabolite_te_ms * 1e-3;
  waterTE = s.reference_te_ms * 1e-3;
  amplMets = s.metabolite_signal; amplWater = s.reference_signal;

  % Buggy: quantH2O multiplies by 1e-3 again
  metsTR_b = metsTR*1e-3; waterTR_b = waterTR*1e-3; metsTE_b = metsTE*1e-3; waterTE_b = waterTE*1e-3;
