            T2_Metab(kk) = mean([T2_Metab_GM(kk) T2_Metab_WM(kk)]);
            T1_Factor(kk) = (1-exp(-waterTR./T1_Water)) ./ (1-exp(-metsTR./T1_Metab(kk)));
            T2_Factor(kk) = exp(-waterTE./T2_Water) ./ exp(-metsTE./T2_Metab(kk));

            % Calculate
            if ~isempty(amplMets{mm,1,ss})
